import{checkEncCryptoKey}from"./crypto_key.js";function checkKeySize(e,t){if(e.algorithm.length!==parseInt(t.slice(1,4),10))throw new TypeError(`Invalid key size for alg: ${t}`)}function getCryptoKey(e,t,r){return e instanceof Uint8Array?crypto.subtle.importKey("raw",e,"AES-KW",!0,[r]):(checkEncCryptoKey(e,t,r),e)}export async function wrap(e,t,r){const a=await getCryptoKey(t,e,"wrapKey");checkKeySize(a,e);const n=await crypto.subtle.importKey("raw",r,{hash:"SHA-256",name:"HMAC"},!0,["sign"]);return new Uint8Array(await crypto.subtle.wrapKey("raw",n,a,"AES-KW"))}export async function unwrap(e,t,r){const a=await getCryptoKey(t,e,"unwrapKey");checkKeySize(a,e);const n=await crypto.subtle.unwrapKey("raw",r,a,"AES-KW",{hash:"SHA-256",name:"HMAC"},!0,["sign"]);return new Uint8Array(await crypto.subtle.exportKey("raw",n))}